// Convert Evolution API base64 response to binary file for Whisper
const items = $input.all();
const outputItems = [];

for (const item of items) {
  try {
    // Evolution API returns: { base64: "...", mimetype: "audio/ogg; codecs=opus" }
    const base64Data = item.json.base64;
    const mimeType = item.json.mimetype || 'audio/ogg; codecs=opus';

    if (!base64Data) {
      throw new Error('No base64 data returned from Evolution API');
    }

    // Determine file extension from mimetype
    let fileExtension = 'ogg';
    if (mimeType.includes('mp3')) fileExtension = 'mp3';
    else if (mimeType.includes('m4a')) fileExtension = 'm4a';
    else if (mimeType.includes('wav')) fileExtension = 'wav';
    else if (mimeType.includes('webm')) fileExtension = 'webm';

    // Convert base64 to binary
    const binaryData = Buffer.from(base64Data, 'base64');

    // Create binary data object for n8n
    item.binary = {
      data: {
        data: binaryData.toString('base64'),
        mimeType: mimeType,
        fileName: `audio.${fileExtension}`,
        fileExtension: fileExtension
      }
    };

    outputItems.push(item);
  } catch (error) {
    throw new Error(`Base64 conversion failed: ${error.message}`);
  }
}

return outputItems;

